local _, Private = ...
local L = Private.L

local _G = _G

-- SkironCooldownManager profile
function Private:Setup_SkironCooldownManager(installer)
	if not Private.IsAddOnLoaded('SkironCooldownManager') then Private:Print('SkironCooldownManager ' .. L["is not installed or enabled."]) return end

	-- Disable unused ElvUI elements
	if Private.ElvUI then
		ElvUI[1].db.unitframe.units.player.castbar.enable = false
		ElvUI[1].db.unitframe.units.player.power.enable = false
		ElvUI[1].private.unitframe.disabledBlizzardFrames.castbar = false
	end

	-- 1080p
	local scaled = Private.Addon.db.global.scaled

	-- Profile name
	local name = (Private.Addon.db.global.dev and 'Luckyone') or 'Luckyone ' .. Private.Version

	-- Profile string
	local importString = (Private.isForever and [[!SCM:1:0!]])
	or [[!SCM:1:0!]]

	-- Profile import
	_G.SCMAPI.ImportProfile(name, importString)

	local DB = _G.SkironCooldownManagerDB
	local profile = DB and DB.profiles[name]
	if scaled and profile then
		profile.options.anchorConfig[1].anchor = { 'CENTER', 'ElvUIParent,UIParent', 'CENTER', 0, -162 } -- 1440p: -222
	end

	Private:Print(L["SkironCooldownManager profile has been set."], installer)
end
